// Para cada proyecto, obtener la lista de ramas
const now = new Date();
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);

const projects = items[0].json;
const results = [];

for (const project of projects) {
  const projectId = project.id;
  const projectName = project.name;
  const namespace = project.namespace?.full_path || 'unknown';

  // Preparar URL para obtener ramas del proyecto
  const branchesUrl = `http://172.24.7.110/api/v4/projects/${projectId}/repository/branches`;

  results.push({
    projectId,
    projectName,
    namespace,
    branchesUrl
  });
}

return results.map(item => ({
  json: item
}));

// Para cada rama en cada proyecto, preparar URL de commits
const results = [];
const now = new Date();
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);

for (const item of items) {
  const projectData = item.json;
  const branches = projectData.branches || [];

  for (const branch of branches) {
    const branchName = branch.name;
    const branchProtected = branch.protected || false;

    // Crear URL para obtener commits de esta rama (últimas 24h)
    const commitsUrl = `http://172.24.7.110/api/v4/projects/${projectData.projectId}/repository/commits?ref_name=${encodeURIComponent(branchName)}&since=${yesterday.toISOString()}&until=${now.toISOString()}`;

    results.push({
      ...projectData,
      branchName,
      branchProtected,
      commitsUrl
    });
  }
}

return results.map(item => ({
  json: item
}));

// Procesar commits por autor, rama, fecha y hora
const metrics = {
  byAuthor: {},
  byBranch: {},
  byHour: {},
  byDate: {},
  topAuthors: [],
  topBranches: []
};

for (const item of items) {
  const projectData = item.json;
  const commits = projectData.commits || [];
  const { projectId, projectName, namespace, branchName } = projectData;

  // Inicializar contadores por rama
  if (!metrics.byBranch[branchName]) {
    metrics.byBranch[branchName] = {
      commitCount: 0,
      linesAdded: 0,
      linesDeleted: 0,
      filesChanged: 0,
      projects: new Set()
    };
  }
  metrics.byBranch[branchName].commitCount += commits.length;
  metrics.byBranch[branchName].projects.add(projectName);

  for (const commit of commits) {
    const authorName = commit.author_name || 'Unknown';
    const authorEmail = commit.author_email || '';
    const commitDate = new Date(commit.committed_date || commit.created_at);
    const dateKey = commitDate.toISOString().split('T')[0];
    const hourKey = commitDate.getUTCHours(); // Hora UTC

    // Estadísticas por autor
    const authorKey = `${authorName}<${authorEmail}>`;
    if (!metrics.byAuthor[authorKey]) {
      metrics.byAuthor[authorKey] = {
        name: authorName,
        email: authorEmail,
        commitCount: 0,
        linesAdded: 0,
        linesDeleted: 0,
        filesChanged: 0,
        branches: new Set(),
        projects: new Set()
      };
    }

    const authorStats = metrics.byAuthor[authorKey];
    authorStats.commitCount++;
    authorStats.branches.add(branchName);
    authorStats.projects.add(projectName);

    // Estadísticas por fecha
    if (!metrics.byDate[dateKey]) {
      metrics.byDate[dateKey] = {
        commitCount: 0,
        uniqueAuthors: new Set(),
        branches: new Set()
      };
    }
    metrics.byDate[dateKey].commitCount++;
    metrics.byDate[dateKey].uniqueAuthors.add(authorKey);
    metrics.byDate[dateKey].branches.add(branchName);

    // Estadísticas por hora
    if (!metrics.byHour[hourKey]) {
      metrics.byHour[hourKey] = {
        commitCount: 0,
        hour: hourKey
      };
    }
    metrics.byHour[hourKey].commitCount++;

    // Obtener estadísticas detalladas del commit (si están disponibles)
    const stats = commit.stats || {};
    authorStats.linesAdded += stats.additions || 0;
    authorStats.linesDeleted += stats.deletions || 0;
    authorStats.filesChanged += stats.total || 0;

    metrics.byBranch[branchName].linesAdded += stats.additions || 0;
    metrics.byBranch[branchName].linesDeleted += stats.deletions || 0;
    metrics.byBranch[branchName].filesChanged += stats.total || 0;
  }
}

// Preparar rankings
metrics.topAuthors = Object.values(metrics.byAuthor)
  .map(a => ({
    ...a,
    branches: Array.from(a.branches),
    projects: Array.from(a.projects),
    netLines: a.linesAdded - a.linesDeleted
  }))
  .sort((a, b) => b.commitCount - a.commitCount)
  .slice(0, 20);

metrics.topBranches = Object.entries(metrics.byBranch)
  .map(([name, data]) => ({
    branchName: name,
    ...data,
    projects: Array.from(data.projects),
    netLines: data.linesAdded - data.linesDeleted
  }))
  .sort((a, b) => b.commitCount - a.commitCount)
  .slice(0, 20);

// Preparar datos para guardar en PostgreSQL
const outputForDB = [];

for (const [authorKey, authorData] of Object.entries(metrics.byAuthor)) {
  for (const branch of authorData.branches) {
    outputForDB.push({
      json: {
        collection_date: new Date().toISOString().split('T')[0],
        author_name: authorData.name,
        author_email: authorData.email,
        branch_name: branch,
        project_count: authorData.projects.size,
        commit_count: authorData.commitCount,
        lines_added: authorData.linesAdded,
        lines_deleted: authorData.linesDeleted,
        files_changed: authorData.filesChanged,
        branches_list: JSON.stringify(Array.from(authorData.branches)),
        projects_list: JSON.stringify(Array.from(authorData.projects)),
        metrics_summary: JSON.stringify({
          topAuthors: metrics.topAuthors,
          topBranches: metrics.topBranches,
          byHour: metrics.byHour,
          byDate: metrics.byDate
        })
      }
    });
  }
}

return outputForDB;
